python3 -c "
from docx import Document
from docx.oxml.ns import qn
doc = Document('/root/offer_letter_template.docx')

# Check all tables more carefully - look at the XML
for ti, table in enumerate(doc.tables):
    for ri, row in enumerate(table.rows):
        for ci, cell in enumerate(row.cells):
            for pi, p in enumerate(cell.paragraphs):
                # Check runs
                for rni, run in enumerate(p.runs):
                    print(f'T{ti}R{ri}C{ci}P{pi}Run{rni}: text={repr(run.text)} bold={run.bold}')

# Also look for nested tables
import lxml.etree as ET
body = doc.element.body
tables = body.findall('.//'+qn('w:tbl'))
print(f'Total tables found in XML: {len(tables)}')
for i, tbl in enumerate(tables):
    rows = tbl.findall(qn('w:tr'))
    print(f'XML Table {i}: {len(rows)} rows')
    for j, row in enumerate(rows):
        cells = row.findall(qn('w:tc'))
        for k, cell in enumerate(cells):
            paras = cell.findall(qn('w:p'))
            for l, p in enumerate(paras):
                text = ''.join(node.text or '' for node in p.iter(qn('w:t')))
                print(f'  R{j}C{k}P{l}: {repr(text)}')
"
